CREATE TABLE accounts(id varchar(255) PRIMARY KEY,name varchar(255) NOT NULL,role varchar(255) NOT NULL CHECK(role IN ('sales','stock','manager')),password varchar(255) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE categories(id varchar(255) PRIMARY KEY,name varchar(255) NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE products(id varchar(255) PRIMARY KEY,name varchar(255) NOT NULL,barcode varchar(255) NOT NULL UNIQUE,category varchar(255) NOT NULL REFERENCES categories(name),unit varchar(255) NOT NULL,price bigint NOT NULL CHECK(price>0),emoji varchar(255),active boolean NOT NULL DEFAULT true);
CREATE TABLE suppliers(id varchar(255) PRIMARY KEY,name varchar(255) NOT NULL,phone varchar(255) NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE batches(id varchar(255) PRIMARY KEY,product_id varchar(255) NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity>=0),expiry date NOT NULL,version bigint NOT NULL DEFAULT 0);
CREATE INDEX batches_fefo ON batches(product_id,expiry,id);
CREATE TABLE receipts(id varchar(255) PRIMARY KEY,supplier varchar(255) NOT NULL REFERENCES suppliers(id),product varchar(255) NOT NULL REFERENCES products(id),batch_id varchar(255) NOT NULL REFERENCES batches(id),accepted integer NOT NULL CHECK(accepted>0),rejected integer NOT NULL CHECK(rejected>=0),note varchar(255),actor varchar(255) NOT NULL REFERENCES accounts(id),at timestamptz NOT NULL);
CREATE TABLE invoices(id varchar(255) PRIMARY KEY,at timestamptz NOT NULL,staff varchar(255) NOT NULL,actor varchar(255) NOT NULL REFERENCES accounts(id),method varchar(255) NOT NULL,total bigint NOT NULL CHECK(total>0),tendered bigint NOT NULL CHECK(tendered>=total),change_due bigint NOT NULL CHECK(change_due=tendered-total));
CREATE TABLE invoice_lines(id varchar(255) PRIMARY KEY,invoice_id varchar(255) NOT NULL REFERENCES invoices(id),product_id varchar(255) NOT NULL REFERENCES products(id),name varchar(255) NOT NULL,quantity integer NOT NULL CHECK(quantity>0),price bigint NOT NULL CHECK(price>0),original_price bigint NOT NULL CHECK(original_price>=price));
CREATE TABLE movements(id varchar(255) PRIMARY KEY,product_id varchar(255) NOT NULL REFERENCES products(id),batch_id varchar(255) NOT NULL REFERENCES batches(id),quantity integer NOT NULL,kind varchar(255) NOT NULL,reference varchar(255) NOT NULL,at timestamptz NOT NULL,actor varchar(255) NOT NULL REFERENCES accounts(id));
CREATE TABLE promotions(id varchar(255) PRIMARY KEY,product_id varchar(255) NOT NULL UNIQUE REFERENCES products(id),percent integer NOT NULL CHECK(percent BETWEEN 1 AND 90),end_date date NOT NULL);
CREATE TABLE stock_counts(id varchar(255) PRIMARY KEY,product_id varchar(255) NOT NULL REFERENCES products(id),batch_id varchar(255) NOT NULL REFERENCES batches(id),expected integer NOT NULL CHECK(expected>=0),actual integer NOT NULL CHECK(actual>=0),base_version bigint NOT NULL,note varchar(255),status varchar(255) NOT NULL CHECK(status IN ('REVIEW','CONFLICT','APPROVED')),actor varchar(255) NOT NULL REFERENCES accounts(id),at timestamptz NOT NULL);
CREATE TABLE store_lock(id varchar(255) PRIMARY KEY);
INSERT INTO store_lock VALUES ('STORE01');
CREATE TABLE operations(id varchar(255) PRIMARY KEY,actor varchar(255) NOT NULL REFERENCES accounts(id),request_body text NOT NULL,response_body text NOT NULL);
CREATE TABLE training_sessions(id varchar(255) PRIMARY KEY,actor varchar(255) NOT NULL REFERENCES accounts(id),chapter integer NOT NULL CHECK(chapter=0),status varchar(255) NOT NULL CHECK(status IN ('ACTIVE','COMPLETED')),visited varchar(255) NOT NULL DEFAULT '',started_at timestamptz NOT NULL,completed_at timestamptz);
